const val SIZE = 1000002
val primes = mutableListOf<Int>()
var minVal = Int.MAX_VALUE

fun sieve() {
    val isComposite = BooleanArray(SIZE)
    for (i in 2 until SIZE) {
        if (!isComposite[i]) {
            primes.add(i)
            if (i.toLong() * i < SIZE) {
                for (j in i * i until SIZE step i) {
                    isComposite[j] = true
                }
            }
        }
    }
}

fun solve(x: Int, l: Int) {
    if (x < minVal) minVal = x
    if (l == 0) return
    var ox = x
    var lf = -1
    for (p in primes) {
        if (p * p > x) break
        if (ox % p == 0) {
            lf = maxOf(lf, p)
            while (ox % p == 0) ox /= p
        }
    }
    if (ox > 1 && ox != x) lf = maxOf(lf, ox)
    if (lf == -1) return
    if (l == 1) {
        val newX = x - lf + 1
        if (newX < minVal) minVal = newX
        return
    }
    for (d in x - lf + 1 until x) {
        solve(d, l - 1)
    }
}

fun main() {
    sieve()
    val x2 = readLine()!!.toInt()
    solve(x2, 2)
    println(minVal)
}

